    connection.execute(sa.text("""
        INSERT INTO public.climates (id, name, description, picture_id, created_at, updated_at, is_active) VALUES
            (3, 'Гумидный климат фреатического типа', 'Климат, в котором осадки превышают испарение, а избыток воды удаляется поверхностным стоком с частичным просачиванием в почву и формированием грунтового питания подземных вод.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 23:19:53.781087+00', TRUE),
            (1, 'Умеренный муссонный климат', 'Тип климата по классификации Алисова Б.П., характерный для восточной Азии. Зимой окраина материка оказывается на периферии азиатского антициклона и здесь преобладает перенос холодного воздуха из Восточной Сибири. Поэтому зима здесь малооблачная и сухая со значительными холодами и резким минимумом осадков. Летом же над востоком Азии господствует циклоническая деятельность с достаточно обильными осадками.', NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (4, 'Континентальный зимний режим муссонного климата', 'Континентальный режим в климате края существует 7-8 месяцев в году; зимой преобладает ясная морозная погода, а годовые амплитуды температуры остаются высокими.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (5, 'Влажный летний муссонный режим', 'Поздней весной и ранним летом юго-восточные ветры приносят прохладный и влажный морской воздух; во второй половине лета поступают очень влажные теплые воздушные массы, сопровождающиеся продолжительными и интенсивными дождями.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (6, 'Влажный климат Приморского края', 'Большая часть ландшафтов Приморского края относится к зоне влажного климата. Муссонная циркуляция вызывает высокую относительную влажность, особенно в теплый период.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (7, 'Климат прибрежных районов Приморского края', 'На побережье Тихого океана годовые амплитуды температуры ниже, чем во внутренних районах, однако остаются достаточно высокими; для побережья характерно влияние туманов, облачности и морского воздуха.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (8, 'Климат горных территорий Приморского края', 'В горных районах проявляется высотная дифференциация климатических условий, включая особенности температуры, снежного покрова, солнечной радиации и осадков.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (9, 'Радиационный режим Приморского края', 'Определяется муссонным характером циркуляции; зимой месячные суммы суммарной и прямой радиации выше, летом ниже из-за туманов и пасмурности.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (10, 'Режим солнечного сияния Приморского края', 'Наибольшее число часов солнечного сияния приходится на континентальные районы края.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (11, 'Температурный режим Приморского края', 'Температурный режим заметно дифференцирован по районам, отражая широтную, долготную и высотную зональность.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (12, 'Ветровой режим Приморского края', 'Определяется наличием противоположных потоков воздуха в зимний и летний периоды.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (13, 'Режим атмосферных осадков Приморского края', 'Отличительной чертой является обилие летних осадков, связанное с муссонной циркуляцией.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (14, 'Снежный режим Приморского края', 'Даты выпадения первого снега близки к датам перехода температуры воздуха через 0 градусов; устойчивый снежный покров формируется через несколько недель после первого снега.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 22:48:37.292476+00', TRUE),
            (2, 'Муссонный климат умеренного пояса', 'Территория Приморского края располагается в муссонной климатической области умеренного пояса. Зимой преобладают холодные и сухие воздушные массы азиатского антициклона; в теплый период преобладает обратная циркуляция с влажным морским воздухом.', NULL, '2026-05-10 22:48:37.292476+00', '2026-05-10 23:19:53.781087+00', TRUE)
    """))

