    connection.execute(sa.text("""
        INSERT INTO public.grounds (id, name, description, density, humidity, solidity, picture_id, created_at, updated_at, is_active) VALUES
            (5, 'Супесчаный', 'Этот грунт по механическому составу тоже считается легким, но он содержит в себе некоторое количество глины, поэтому лучше удерживает воздух, воду и питательные вещества, хорошо прогревается и не так быстро остывает. Супесчаный грунт легко обрабатывать, а выращивать на нем можно практически любую культуру, однако желательно поддерживать плодородность внесением органики, выращиванием и заделкой сидератов и регулярным мульчированием.', 8.2, 6.3, 9.6, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (6, 'Суглинистый', 'Для выращивания садово-огородных культур суглинок является одним из лучших грунтов: он питателен, тепло-, водо- и воздухопроницаем, его легко обрабатывать. Главное, его нет необходимости улучшать, нужно только поддерживать плодородность грунта мульчированием и внесением под перекопку навоза из расчета 3-4 кг/м². А выращиваемые в суглинке культуры следует регулярно подкармливать минеральными комплексами.', 7.2, 6.3, 7.1, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (7, 'Известковый', 'Известковые грунты могут быть тяжелыми или легкими, но все они бедные. Они включают много каменистых фрагментов, их pH сдвинут в щелочную сторону, они быстро нагреваются и высыхают, блокируют усвоение культурами марганца и железа, отчего у них желтеют листья и происходит задержка роста. Улучшить структуру грунта можно регулярным внесением органики под перекопку и использованием ее в виде мульчи, выращиванием и заделкой в верхний слой сидеральных культур, внесением калийных удобрений. После окультуривания в известковых грунтах можно выращивать любые культуры при условии своевременного полива, регулярных рыхлений междурядий и разумного внесения органических и минеральный удобрений.', 2.3, 6.3, 6.1, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (8, 'Торфяной', 'Торфяные, или болотистые грунты тоже нельзя назвать подходящими для земледелия, поскольку питательные элементы в них находятся в форме, недоступной для усвоения растениями. Эти грунты быстро впитывают и так же быстро отдают воду, медленно прогреваются и как правило закислены. Положительными качествами торфяной почвы можно считать то, что она подаются окультуриванию и задерживает в себе минеральные удобрения. Чтобы повысить плодородность торфяной почвы, ее глубоко перекапывают с глиняной мукой или песком, сильно закисленные участки известкуют, а в дальнейшем регулярно удобряют органикой – навозной жижей, компостом, перегноем, микробиологическими добавками и калийно-фосфорными удобрениями. При высаживании деревьев посадочные котлованы нужно заполнять специально составленной подходящей для культуры почвенной смесью, а при разбивке на торфяниках овощных грядок поступают так, как и с песчаным грунтом: укладывают в качестве основы глиняную прослойку, а поверх нее делают грядки из смеси торфа с суглинком, органическими удобрениями и известью.', 4.2, 6.3, 2.3, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (9, 'Чернозёмный', 'Чернозёмы – грунты высокой плодородности с устойчивой структурой, высоким содержанием гумуса и достаточным количеством кальция и других питательных элементов. Они хорошо поглощают и удерживают воздух, воду и тепло, поэтому для выращивания овощных, цветочных и плодово-ягодных культур являются лучшими из всех видов грунта. Но чернозём со временем истощается, и через 2-3 года непрерывного использования он требует внесения удобрений или восстановления структуры за счет выращивания сидератов. Нужно сказать, что чернозём не является легким грунтом, и под некоторые культуры его приходится перекапывать с торфом или песком. Кроме того, его реакция может быть как нейтральной, так и сдвинутой в щелочную или кислую сторону, поэтому чернозем может требовать как раскисления, так и расщелачивания.', 5.8, 7.3, 4.5, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (1, 'Глинистый', 'Этот тяжёлый грунт плохо поддается обработке, очень долго сохнет и греется. Как правило, глинистый грунт имеет кислую реакцию, плохо пропускает питание, тепло, влагу и воздух к корням растений, в нем нет условий для развития полезных микроорганизмов, а растительные остатки в глине очень долго разлагаются. Из-за того, что глинистый грунт долго высыхает после таяния снега и медленно прогревается, посадку культур приходится задерживать. Чтобы улучшить состав грунта, в него нужно вносить под перекопку крупнозернистый песок, торф и перегной, а для нейтрализации кислой реакции глинистую почву нужно один раз в три года известковать.', 1.1, 2.3, 8.3, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (2, 'Песчаный', 'Песчаный грунт отличается рыхлостью, легкостью, сыпучестью, он легко пропускает воздух, воду, тепло и подкормки к корням растений, однако эти достоинства одновременно являются и недостатками: песчаные грунты быстро высыхают, остывают, а питательные вещества легко из них вымываются. Чтобы повысить плодородность песчаного грунта, необходимо регулярно вносить в него уплотняющие и связующие вещества: торф, перегной, компост, выращивать и заделывать в грунт сидераты, проводить мульчирование поверхности.', 4.4, 1.3, 1.4, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (3, 'Гравиевый', 'Этот тип грунта состоит преимущественно из гравия, который представляет собой обломки горных пород размером от 2 до 60 миллиметров. Гравийные грунты обладают хорошей дренирующей способностью и часто используются в строительстве для создания устойчивых оснований.', 2.8, 3.6, 11.2, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (4, 'Гальковый', 'Гальковый грунт состоит из гальки, которая представляет собой округлые обломки горных пород размером от 10 до 100 миллиметров, сформированные в результате водной эрозии. Такие грунты обычно встречаются в речных долинах и на побережьях, обеспечивая хорошую водопроницаемость и устойчивость к эрозии.', 3.2, 2.1, 9.6, NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE)
    """))

    connection.execute(sa.text(f"ALTER TABLE public.grounds ENABLE TRIGGER ALL"))


    # --- public.landscapes: 2877 rows ---
