            (3, 'Владивосток', 3, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (4, 'Надеждинский район', 4, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (5, 'Полуостров Песчаный, внутренняя часть', 5, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (6, 'Полуостров Песчаный, наружная часть', 6, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (7, 'Остров Шкота', 7, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (8, 'Остров Рейнеке', 8, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (9, 'Остров Попова', 9, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (10, 'Бухта Теляковского', 10, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (11, 'Остров Русский', 11, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
