    connection.execute(sa.text("""
        INSERT INTO public.waters (id, name, description, picture_id, created_at, updated_at, is_active) VALUES
            (1, 'Река Лазурная (Шамора)', 'Река Шамора, также известная как река Лазурная, впадает в бухту Шамора (бухта Лазурная) в Приморском крае.', NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (2, 'Река Богатая', 'Богатая (Лянчихе) — река на юге Приморского края, протекает по территории полуострова Муравьёва-Амурского, является самой крупной рекой в пределах Владивостока. Длина реки — около 19 км, площадь водосборного бассейна — 69 км². Берёт начало на склонах горы Природный Пуп. Направление течения — западное (с небольшим отклонением на юг). В верхней и средней частях течёт по лесам, в низовьях протекает по северной части Владивостока. Впадает в бухту Бражникова Амурского залива в нескольких сотнях метров северо-восточнее железнодорожной станции Океанская.', NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (3, 'Река Кневичанка', 'Кневичанка (Тангауза) — река в Приморском крае России, основная водная артерия города Артёма, протекающая по северо-восточной окраине города. Является правым притоком реки Артёмовки, которая фактически имеет с Кневичанкой общий эстуарий длиной около 4 км, выходящий в Муравьиную бухту Уссурийского залива Японского моря. Бассейн Кневичанки занимает свыше 80 % общей площади города.', NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (4, 'Река Суходол', 'Суходол (Кангауз) — река в Шкотовском районе Приморского края России. Река берёт своё начало на юго-восточном склоне горы Туманной, хребта Большой Воробей, расположенного в южной части горной системы Сихотэ-Алиня. Течёт в западном направлении и впадает у села Речица в бухту Суходол Уссурийского залива. Длина реки 45 км, падение — 617 м.', NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (5, 'Грунтовые воды', 'Грунтовые воды – это подземные воды, залегающие в первом от поверхности водоупорном слое. Они формируются в результате просачивания атмосферных осадков и поверхностных вод через почву и породы. В отличие от артезианских вод, грунтовые воды не обладают напором и их уровень может меняться в зависимости от времени года и количества осадков.', NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (6, 'Артезианские воды', 'Артезианские воды - это напорные подземные воды, заключенные между двумя водоупорными слоями горных пород. Они характеризуются тем, что находятся под давлением и могут выходить на поверхность, иногда даже фонтанировать, при вскрытии водоносного горизонта скважиной.', NULL, '2026-05-10 09:15:23.475715+00', '2026-05-10 09:15:23.475715+00', TRUE),
            (7, 'Водотоки равнинного и долинного горного типов ландшафтов', 'Отличаются крайне неустойчивым режимом. Паводки возможны в любое время теплой половины года, распределение стока во времени и по территории неравномерно.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (8, 'Водотоки восточных склонов Сихотэ-Алиня', 'Характерны значительные подъемы воды весной и сравнительно небольшие паводки; лесная растительность играет выраженную водорегулирующую роль.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (9, 'Водотоки южной части Приморья', 'Для водотоков южной части края выделяются фазы весенне-летнего и летне-осеннего стока с максимумами в мае и августе-сентябре.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (10, 'Водотоки западного макросклона Сихотэ-Алиня', 'Имеют хорошо выраженные весенне-летние и летне-осенние паводки с резкими подъемами, спадами и высокими максимальными расходами.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (11, 'Реки Уссури-Ханкайской равнины', 'В восточной части равнины водность рек весной выше летне-осеннего периода; в западной части равнины зимний сток наиболее низкий в крае.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (12, 'Верховодка', 'Временное скопление воды в зоне аэрации выше постоянного первого от поверхности водоносного горизонта.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (13, 'Водоносный горизонт рыхлых аллювиальных, озерно-аллювиальных и озерных отложений', 'Связан с аллювиальными, озерно-аллювиальными и озерными отложениями речных долин и равнинных территорий.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (14, 'Водоносный комплекс рыхлых морских и аллювиально-морских отложений', 'Имеет ограниченное распространение, преимущественно связан с низинными прибрежными участками и морскими либо аллювиально-морскими отложениями.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (15, 'Воды спорадического распространения делювиальных, элювиальных, нерасчлененных склоновых и оползневых образований', 'Связаны с делювиальными, элювиальными, склоновыми и оползневыми образованиями ландшафтов.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (16, 'Водоносный комплекс неогеновых базальтов', 'Пространственно связан с эффузивными полями и плато базальтов неогенового возраста.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (17, 'Водоносный комплекс рыхлых накоплений неогена', 'Развит в юго-западной и западной частях Приморья и связан с рыхлыми накоплениями неогенового возраста.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (18, 'Водоносный комплекс рыхлых накоплений палеогена', 'Объединяет водоносные комплексы рыхлых накоплений палеогена, включая майтунскую, угловскую и надеждинскую свиты.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (19, 'Воды эффузивных пород палеогена и верхнего мела', 'Связаны с эффузивными породами фундамента преимущественно горного типа ландшафтов.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (20, 'Воды мезозойских отложений', 'Связаны с осадочными отложениями и внутриформационными вулканогенными образованиями мезозойского возраста.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (21, 'Воды верхне- и среднепалеозойских отложений', 'Связаны с верхне- и среднепалеозойскими отложениями, представленными чередованием терригенных и вулканогенных толщ.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (22, 'Воды нижнепалеозойских и протерозойских отложений', 'Распространены в пределах Ханкайского массива и связаны с нижнепалеозойскими и протерозойскими отложениями.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (23, 'Подземные воды гранитоидов', 'Связаны с гранитоидными породами фундамента ландшафтов; такие породы широко распространены в Приморском крае.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (24, 'Подземные воды габброидов', 'Имеют незначительное распространение; обычно относятся к пресным гидрокарбонатным водам кальциевой, реже натриевой группы.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (25, 'Паводочный режим рек', 'В Приморье наблюдаются два паводочных периода: весенне-летний и летне-осенний.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (26, 'Весенне-летний сток', 'Фаза стока, характерная для части водотоков Приморья в апреле-июне.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (27, 'Летне-осенний сток', 'Фаза стока, связанная с дождевыми паводками и максимумами в теплый период.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (28, 'Зимний меженный сток', 'Зимний сток значительно ниже летнего; многие реки периодически перемерзают и пересыхают.', NULL, '2026-05-10 22:48:43.586917+00', '2026-05-10 22:48:43.586917+00', TRUE),
            (29, 'Болотные и переувлажнённые водные комплексы', 'Болотные, торфянистые и переувлажнённые участки ландшафтов.', NULL, '2026-05-10 23:19:53.781087+00', '2026-05-10 23:19:53.781087+00', TRUE),
            (30, 'Озёрные и приозёрные водные объекты', 'Озёрные и приозёрные участки ландшафтов.', NULL, '2026-05-10 23:19:53.781087+00', '2026-05-10 23:19:53.781087+00', TRUE),
            (31, 'Пойменные и террасовые водные комплексы', 'Водные и околоводные комплексы пойм, надпойменных террас и террасированных долин.', NULL, '2026-05-10 23:19:53.781087+00', '2026-05-10 23:19:53.781087+00', TRUE),
            (32, 'Прибрежно-морские водные комплексы', 'Прибрежные, морские и япономорские участки ландшафтов.', NULL, '2026-05-10 23:19:53.781087+00', '2026-05-10 23:19:53.781087+00', TRUE),
            (33, 'Реки и речные долины', 'Поверхностные водные объекты и долинные участки, выделенные по указаниям на реки, притоки, верховья, правобережья и левобережья.', NULL, '2026-05-10 23:19:53.781087+00', '2026-05-10 23:19:53.781087+00', TRUE)
    """))

    connection.execute(sa.text(f"ALTER TABLE public.waters ENABLE TRIGGER ALL"))



